function checkoutPage(){if(!cart.length)return pageHero('CHECKOUT',t('إتمام الطلب','Checkout'))+`<section class="gr16-section"><div class="gr16-container gr16-empty"><h2>${t('السلة فارغة','Your cart is empty')}</h2><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('العودة للمتجر','Back to shop')}</a></div></section>`;const draft=get(K.draft,{});return `<section class="gr17-checkout-head"><div class="gr16-container"><a href="${url('index.html')}"><img src="assets/golden-roots-logo.webp" alt="GOLDEN ROOTS"></a><span>${t('إتمام الطلب','Checkout')}</span></div></section><section class="gr16-section"><div class="gr16-container gr16-checkout-layout"><div><div class="gr17-stepper"><span class="is-active" data-step-dot="1">1 <b>${t('البيانات','Details')}</b></span><span data-step-dot="2">2 <b>${t('العنوان','Address')}</b></span><span data-step-dot="3">3 <b>${t('الدفع','Payment')}</b></span></div><form class="gr16-panel gr16-form gr17-checkout-form" data-checkout-form><section data-checkout-step="1"><h2>${t('بيانات التواصل','Contact details')}</h2><div class="gr16-form-grid"><label>${t('الاسم الكامل','Full name')}<input name="name" required value="${esc(draft.name||'')}"></label><label>${t('رقم الهاتف','Phone')}<input name="phone" required inputmode="tel" value="${esc(draft.phone||'')}"></label><label>${t('البريد الإلكتروني','Email')}<input name="email" type="email" value="${esc(draft.email||'')}"></label></div><button type="button" class="gr16-btn gr16-btn--primary" data-next-step="2">${t('التالي: العنوان','Next: address')}</button></section><section data-checkout-step="2" hidden><h2>${t('عنوان التوصيل','Delivery address')}</h2><div class="gr16-form-grid"><label>${t('الإمارة','Emirate')}<select name="emirate" required><option value="">${t('اختر الإمارة','Select emirate')}</option>${['Dubai','Abu Dhabi','Sharjah','Ajman','Umm Al Quwain','Ras Al Khaimah','Fujairah'].map(x=>`<option ${draft.emirate===x?'selected':''}>${x}</option>`).join('')}</select></label><label>${t('المدينة / المنطقة','City / Area')}<input name="area" required value="${esc(draft.area||'')}"></label><label class="gr17-span-2">${t('العنوان بالتفصيل','Full address')}<input name="address" required value="${esc(draft.address||'')}"></label><label class="gr17-span-2">${t('ملاحظات التوصيل','Delivery notes')}<textarea name="notes">${esc(draft.notes||'')}</textarea></label></div><div class="gr17-step-actions"><button type="button" class="gr16-btn gr16-btn--outline" data-prev-step="1">${t('السابق','Back')}</button><button type="button" class="gr16-btn gr16-btn--primary" data-next-step="3">${t('التالي: الدفع','Next: payment')}</button></div></section><section data-checkout-step="3" hidden><h2>${t('طريقة الدفع','Payment method')}</h2><div class="gr16-paymethods"><label class="gr16-paymethod"><input type="radio" name="payment" value="card" checked><div><b>${t('بطاقة بنكية','Bank card')}</b><span>${t('واجهة جاهزة للربط ببوابة الدفع عند الإطلاق','Ready for payment-gateway connection at launch')}</span></div></label><label class="gr16-paymethod"><input type="radio" name="payment" value="cod"><div><b>${t('الدفع عند الاستلام','Cash on delivery')}</b><span>${t('يظهر كخيار عند اعتماده تشغيليًا','Available when operationally enabled')}</span></div></label></div><div class="gr17-step-actions"><button type="button" class="gr16-btn gr16-btn--outline" data-prev-step="2">${t('السابق','Back')}</button><button class="gr16-btn gr16-btn--primary" type="submit">${t('تأكيد الطلب التجريبي','Confirm test order')}</button></div></section></form></div><aside class="gr16-summary"><h3>${t('طلبك','Your order')}</h3>${cart.map(lineData).filter(Boolean).map(d=>`<div class="gr17-check-line"><span>${esc(d.p[isAR?'ar':'en'])} × ${d.qty}</span><b>${money(d.price*d.qty)}</b></div>`).join('')}<div class="gr16-summary-row total"><span>${t('الإجمالي','Total')}</span><strong>${money(total())}</strong></div></aside></div></section>`}
function orderConfirmationPage(){const oid=params.get('order');const o=orders.find(x=>x.id===oid)||orders[0];if(!o)return pageHero('ORDER',t('لا يوجد طلب محفوظ','No saved order'))+`<section class="gr16-section"><div class="gr16-container gr16-empty"><a class="gr16-btn gr16-btn--primary" href="${url('index.html')}">${t('الرئيسية','Home')}</a></div></section>`;return `<section class="gr16-section"><div class="gr16-container gr17-confirm"><div class="gr17-success-mark">✓</div><span class="gr16-kicker">${esc(o.id)}</span><h1>${t('تم إنشاء الطلب التجريبي بنجاح','Test order created successfully')}</h1><p>${t('تم حفظ نسخة الطلب على هذا الجهاز لاختبار رحلة المستخدم كاملة قبل ربط نظام الطلبات الحقيقي.','The order was saved on this device to test the complete customer journey before live order integration.')}</p><div class="gr16-panel"><div class="gr16-summary-row"><span>${t('الاسم','Name')}</span><b>${esc(o.customer.name)}</b></div><div class="gr16-summary-row"><span>${t('الإمارة','Emirate')}</span><b>${esc(o.customer.emirate)}</b></div><div class="gr16-summary-row"><span>${t('الإجمالي','Total')}</span><b>${money(o.total)}</b></div></div><div class="gr17-step-actions"><a class="gr16-btn gr16-btn--primary" href="${url('account.html')}">${t('عرض طلباتي','View my orders')}</a><a class="gr16-btn gr16-btn--outline" href="${url('collection.html')}">${t('متابعة التسوق','Continue shopping')}</a></div></div></section>`}
function wishlistPage(){const rows=wish.map(product).filter(Boolean);return pageHero('WISHLIST',t('المفضلة','Wishlist'),t('منتجات حفظتها للرجوع إليها بسرعة.','Products you saved for quick access.'))+`<section class="gr16-section"><div class="gr16-container">${rows.length?grid(rows):`<div class="gr16-empty"><h2>${t('المفضلة فارغة','Your wishlist is empty')}</h2><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('تصفح المنتجات','Browse products')}</a></div>`}</div></section>`}
function comparePage(){const rows=compare.map(product).filter(Boolean);return pageHero('COMPARE',t('مقارنة المنتجات','Compare Products'),t('قارن حتى 4 منتجات جنبًا إلى جنب.','Compare up to 4 products side by side.'))+`<section class="gr16-section"><div class="gr16-container">${rows.length?`<div class="gr16-table-wrap"><table class="gr16-table gr17-compare-table"><thead><tr><th>${t('المعيار','Attribute')}</th>${rows.map(p=>`<th><img src="${p.img}" alt=""><a href="${url('product.html',{id:p.id})}">${esc(p[isAR?'ar':'en'])}</a><button data-compare="${p.id}">×</button></th>`).join('')}</tr></thead><tbody><tr><td>${t('السعر','Price')}</td>${rows.map(p=>`<td>${money(p.price)}</td>`).join('')}</tr><tr><td>SKU</td>${rows.map(p=>`<td>${esc(p.sku)}</td>`).join('')}</tr><tr><td>${t('التوفر','Availability')}</td>${rows.map(p=>`<td>${p.stock>0?t('متوفر','In stock'):t('غير متوفر','Out of stock')}</td>`).join('')}</tr><tr><td>${t('النوع','Type')}</td>${rows.map(p=>`<td>${esc(t(p.type_ar,p.type_en))}</td>`).join('')}</tr></tbody></table></div>`:`<div class="gr16-empty"><h2>${t('لم تختر منتجات للمقارنة','No products selected')}</h2><a class="gr16-btn gr16-btn--primary" href="${url('collection.html')}">${t('اختيار منتجات','Choose products')}</a></div>`}</div></section>`}
function quickOrderPage(){return pageHero('QUICK ORDER',t('الطلب السريع للمزارع','Farm Quick Order'),t('حدد الكمية لكل منتج ثم أضف الطلب كله للسلة مرة واحدة.','Set quantities and add the whole order to cart in one action.'))+`<section class="gr16-section"><div class="gr16-container"><div class="gr16-panel"><input class="gr16-filter-input" data-qofilter placeholder="${t('ابحث بالاسم أو SKU...','Search by name or SKU...')}"><div class="gr16-table-wrap"><table class="gr16-table"><thead><tr><th>${t('المنتج','Product')}</th><th>SKU</th><th>${t('السعر','Price')}</th><th>${t('التوفر','Stock')}</th><th>${t('الكمية','Qty')}</th></tr></thead><tbody>${P.map(p=>`<tr data-qorow data-search="${esc(norm(p.ar+' '+p.en+' '+p.sku))}"><td><a href="${url('product.html',{id:p.id})}">${esc(p[isAR?'ar':'en'])}</a></td><td>${esc(p.sku)}</td><td>${money(p.price)}</td><td>${p.stock}</td><td><input data-qoqty="${p.id}" type="number" min="0" max="999" value="0" ${p.stock<=0?'disabled':''}></td></tr>`).join('')}</tbody></table></div><button class="gr16-btn gr16-btn--primary" data-qoadd>${t('إضافة الكميات المحددة للسلة','Add selected quantities to cart')}</button></div></div></section>`}
function savedListsPage(){const names=Object.keys(lists);return pageHero('FARM LISTS',t('قوائم المزرعة','Farm Lists'),t('احفظ مجموعات منتجات متكررة لاستخدامها مرة أخرى.','Save reusable groups of products for repeat purchasing.'))+`<section class="gr16-section"><div class="gr16-container"><div class="gr17-create-list"><input data-new-list placeholder="${t('اسم القائمة، مثال: طلب المزرعة الشهري','List name, e.g. Monthly farm order')}"><button class="gr16-btn gr16-btn--primary" data-create-list>${t('إنشاء قائمة','Create list')}</button></div>${names.length?`<div class="gr17-list-grid">${names.map(n=>`<article class="gr16-panel"><div class="gr16-head"><div><h2>${esc(n)}</h2><span>${lists[n].length} ${t('منتجات','products')}</span></div><button class="gr16-linkbtn" data-list-delete="${esc(n)}">${t('حذف','Delete')}</button></div><div class="gr17-mini-products">${lists[n].map(product).filter(Boolean).map(p=>`<a href="${url('product.html',{id:p.id})}"><img src="${p.img}" alt=""><span>${esc(p[isAR?'ar':'en'])}</span></a>`).join('')||`<p>${t('القائمة فارغة. أضف منتجات من صفحة المنتج.','This list is empty. Add products from a product page.')}</p>`}</div><button class="gr16-btn gr16-btn--outline" data-list-addall="${esc(n)}">${t('إضافة القائمة للسلة','Add list to cart')}</button></article>`).join('')}</div>`:`<div class="gr16-empty"><h2>${t('لسه مفيش قوائم محفوظة','No saved lists yet')}</h2><p>${t('أنشئ أول قائمة ثم أضف لها المنتجات من صفحات المنتجات.','Create your first list, then add products from product pages.')}</p></div>`}</div></section>`}
function brandsPage(){const brands=[...new Set(P.map(p=>p.brand))];return pageHero('BRANDS',t('العلامات التجارية','Brands'),t('تصفح المنتجات حسب العلامة التجارية.','Browse products by brand.'))+`<section class="gr16-section"><div class="gr16-container gr17-brand-grid">${brands.map(b=>`<a class="gr16-panel" href="${url('collection.html',{brand:b})}"><span class="gr17-brand-mark">GR</span><h2>${esc(b)}</h2><p>${P.filter(p=>p.brand===b).length} ${t('منتج','products')}</p></a>`).join('')}</div></section>`}
function accountPage(){const saved=get('gr17_saved_cart',[]);return pageHero('ACCOUNT',t('حسابي','My Account'),t('لوحة تجربة للحساب والطلبات والقوائم المحفوظة قبل ربط تسجيل الدخول الحقيقي.','Account, orders and saved-list experience before live authentication integration.'))+`<section class="gr16-section"><div class="gr16-container"><div class="gr17-account-cards"><a class="gr16-panel" href="${url('wishlist.html')}"><b>${wish.length}</b><span>${t('في المفضلة','Wishlist items')}</span></a><a class="gr16-panel" href="${url('saved-lists.html')}"><b>${Object.keys(lists).length}</b><span>${t('قوائم مزرعة','Farm lists')}</span></a><div class="gr16-panel"><b>${orders.length}</b><span>${t('طلبات محفوظة','Saved orders')}</span></div><div class="gr16-panel"><b>${recent.length}</b><span>${t('شوهد مؤخرًا','Recently viewed')}</span></div></div><div class="gr16-head"><div><span class="gr16-kicker">${t('الطلبات','ORDERS')}</span><h2>${t('طلباتي الأخيرة','Recent orders')}</h2></div></div>${orders.length?`<div class="gr17-orders">${orders.map(o=>`<article class="gr16-panel"><div><b>${esc(o.id)}</b><span>${new Date(o.date).toLocaleDateString(isAR?'ar-AE':'en-AE')}</span></div><div><strong>${money(o.total)}</strong><span>${o.items.length} ${t('منتجات','items')}</span></div><div><a href="${url('order-confirmation.html',{order:o.id})}">${t('التفاصيل','Details')}</a><button data-reorder="${o.id}">${t('إعادة الطلب','Reorder')}</button></div></article>`).join('')}</div>`:`<div class="gr16-empty"><p>${t('لا توجد طلبات محفوظة على هذا الجهاز حتى الآن.','No orders are saved on this device yet.')}</p></div>`}${saved.length?`<section class="gr16-panel gr17-saved-cart"><div><h2>${t('سلة محفوظة','Saved cart')}</h2><p>${saved.length} ${t('أسطر منتجات محفوظة','saved cart lines')}</p></div><button class="gr16-btn gr16-btn--outline" data-restore-cart>${t('استعادة السلة','Restore cart')}</button></section>`:''}</div></section>`}
function wholesalePage(){return pageHero('FARM & B2B',t('طلبات المزارع والشركات','Farm & Business Orders'),t('جهز طلب كميات أو اطلب عرض سعر لمجموعة منتجات.','Prepare a volume order or request a quote for multiple products.'))+`<section class="gr16-section"><div class="gr16-container gr16-quote-grid"><div class="gr16-quote-aside"><span class="gr16-kicker">B2B</span><h2>${t('مسار أبسط للطلبات الكبيرة','A simpler path for volume orders')}</h2><p>${t('اكتب بياناتك واحتياجك، أو استخدم الطلب السريع لو عندك قائمة منتجات واضحة.','Share your details and requirements, or use Quick Order if you already know the products.')}</p><a class="gr16-btn gr16-btn--outline" href="${url('quick-order.html')}">${t('فتح الطلب السريع','Open quick order')}</a></div><form class="gr16-panel gr16-form" data-quote-form><div class="gr16-form-grid"><label>${t('اسم الشركة / المزرعة','Company / farm name')}<input required name="company"></label><label>${t('اسم المسؤول','Contact person')}<input required name="name"></label><label>${t('الهاتف','Phone')}<input required name="phone"></label><label>${t('الإمارة','Emirate')}<input required name="emirate"></label><label class="gr17-span-2">${t('تفاصيل المنتجات والكميات','Products and quantities')}<textarea required name="details"></textarea></label></div><button class="gr16-btn gr16-btn--primary">${t('حفظ طلب عرض السعر','Save quote request')}</button></form></div></section>`}
const staticPages={about:{k:'ABOUT',ar:'من نحن',en:'About Golden Roots',body_ar:'جولدن روتس للزراعة ومستلزماتها منصة تجارة زراعية مصممة لتسهيل الوصول للبذور والأسمدة وحماية المحاصيل والري والأدوات ومستلزمات البيوت المحمية.',body_en:'Golden Roots Agriculture & Supplies is an agricultural commerce experience designed to make seeds, nutrition, crop protection, irrigation, tools and greenhouse supplies easier to discover.'},contact:{k:'CONTACT',ar:'تواصل معنا',en:'Contact Us'},shipping:{k:'SHIPPING',ar:'الشحن والتوصيل',en:'Shipping & Delivery',copy_ar:'نجهز تجربة الشحن لتغطي الإمارات السبع، وتظهر تفاصيل الرسوم والمدة النهائية بوضوح قبل تأكيد الطلب.',copy_en:'The delivery experience is designed for all seven emirates, with final fees and timing shown clearly before an order is confirmed.'},returns:{k:'RETURNS',ar:'الاسترجاع والاستبدال',en:'Returns & Exchanges',copy_ar:'سياسة الاسترجاع تعرض شروط أهلية المنتج وحالته والمدة المعتمدة بطريقة واضحة قبل الإطلاق التجاري.',copy_en:'The returns policy will clearly state product eligibility, condition and the approved return window before commercial launch.'},privacy:{k:'PRIVACY',ar:'سياسة الخصوصية',en:'Privacy Policy',copy_ar:'صفحة مخصصة لشرح كيفية التعامل مع بيانات العملاء وطلبات التواصل عند تشغيل الخدمات الحقيقية.',copy_en:'A dedicated page for explaining how customer and contact-request data is handled when live services are enabled.'},terms:{k:'TERMS',ar:'الشروط والأحكام',en:'Terms & Conditions',copy_ar:'الإطار العام لاستخدام الموقع وعمليات الطلب والخدمات المقدمة عبر جولدن روتس.',copy_en:'The general framework for using the website, ordering and services provided through Golden Roots.'}};
function staticPage(kind){const x=staticPages[kind];let body='';if(kind==='about')body=`<div class="gr16-policy"><h2>${t('رؤيتنا','Our approach')}</h2><p>${t(x.body_ar,x.body_en)}</p><h2>${t('تجربة عملية','A practical experience')}</h2><p>${t('بحث واضح، أقسام منظمة، طلب سريع للكميات، ومسارات مختلفة للأفراد والمزارع والشركات.','Clear search, organized categories, quick volume ordering and distinct flows for individuals, farms and businesses.')}</p></div>`;else if(kind==='contact')body=`<div class="gr16-quote-grid"><div class="gr16-quote-aside"><h2>${t('كيف نقدر نساعدك؟','How can we help?')}</h2><p>${t('للاستفسارات العامة استخدم النموذج، ولطلبات الكميات استخدم مسار المزارع والشركات.','Use the form for general questions, and Farm & B2B for volume requests.')}</p></div><form class="gr16-panel gr16-form" data-contact-form><label>${t('الاسم','Name')}<input required name="name"></label><label>${t('الهاتف أو البريد','Phone or email')}<input required name="contact"></label><label>${t('الرسالة','Message')}<textarea required name="message"></textarea></label><button class="gr16-btn gr16-btn--primary">${t('حفظ الرسالة','Save message')}</button></form></div>`;else body=`<div class="gr16-policy"><h2>${t('معلومات أساسية','Key information')}</h2><p>${t(x.copy_ar,x.copy_en)}</p><h2>${t('قبل الإطلاق التجاري','Before commercial launch')}</h2><p>${t('سيتم إدخال النص القانوني والتشغيلي المعتمد من الشركة داخل نفس التصميم الحالي.','The company-approved legal and operational wording will be inserted into this same design.')}</p></div>`;return pageHero(x.k,t(x.ar,x.en))+`<section class="gr16-section"><div class="gr16-container">${body}</div></section>`}
function faqPage(){const items=[[t('هل التوصيل متاح داخل كل الإمارات؟','Is delivery available across all emirates?'),t('تصميم الطلب يدعم الإمارات السبع، وتُعتمد الرسوم والمدة النهائية وقت التشغيل التجاري.','The ordering flow supports all seven emirates; final rates and timing are configured for commercial launch.')],[t('هل يمكن طلب كميات للمزرعة أو الشركة؟','Can farms or companies order in bulk?'),t('نعم، يوجد طلب سريع وقوائم مزرعة ومسار مستقل لطلب عرض سعر.','Yes. Quick Order, Farm Lists and Request Quote are all available.')],[t('هل أقدر أرجع لسلة أو منتجات شاهدتها؟','Can I return to a cart or products I viewed?'),t('نعم، النسخة الحالية تحفظ السلة والمفضلة والقوائم والمنتجات المشاهدة محليًا على الجهاز.','Yes. The current site saves cart, wishlist, lists and viewed products locally on the device.')],[t('هل الموقع قابل للتثبيت على الموبايل؟','Can the site be installed on mobile?'),t('نعم عند تشغيله عبر HTTPS يمكن تثبيته كتطبيق ويب PWA على الأجهزة المدعومة.','Yes. When served over HTTPS it can be installed as a PWA on supported devices.')]];return pageHero('FAQ',t('الأسئلة الشائعة','Frequently Asked Questions'))+`<section class="gr16-section"><div class="gr16-container gr16-accordion">${items.map(x=>`<details><summary>${x[0]}</summary><p>${x[1]}</p></details>`).join('')}</div></section>`}
function notFound(){return `<section class="gr16-section"><div class="gr16-container gr16-empty" style="margin-top:50px"><span class="gr16-kicker">404</span><h1 class="gr17-404">${t('الصفحة غير موجودة','Page not found')}</h1><p>${t('الرابط قديم أو تمت إزالته. استخدم البحث أو ارجع للرئيسية.','The link may be old or removed. Use search or return home.')}</p><div class="gr17-step-actions"><button class="gr16-btn gr16-btn--outline" data-search-open>${t('بحث','Search')}</button><a class="gr16-btn gr16-btn--primary" href="${url('index.html')}">${t('الرئيسية','Home')}</a></div></div></section>`}
function renderSearch(q=''){const box=qs('[data-search-results]');if(!box)return;const rows=searchProducts(q).slice(0,8);box.innerHTML=rows.map(p=>`<a class="gr16-search-item" href="${url('product.html',{id:p.id})}"><img src="${p.img}" alt=""><div><strong>${esc(p[isAR?'ar':'en'])}</strong><small>${esc(p.sku)} · ${catName(p.cat)}</small></div><b>${money(p.price)}</b></a>`).join('')||`<div class="gr16-empty"><strong>${t('لا توجد نتائج','No results')}</strong><span>${t('جرّب كلمة أقصر مثل: سماد، بذور، ري.','Try a shorter term such as fertilizer, seeds or irrigation.')}</span></div>`;const h=qs('[data-search-history]'),hist=get(K.searches,[]);if(h)h.innerHTML=hist.length?`<span>${t('بحثت مؤخرًا:','Recent:')}</span>${hist.map(x=>`<a href="${url('search.html',{q:x})}">${esc(x)}</a>`).join('')}`:''}
function renderMain(){const main=qs('[data-v17-page]');if(!main)return;const pg=main.dataset.v17Page;const f={home,collections:collectionsPage,collection:collectionPage,product:productPage,offers:offersPage,search:searchPage,cart:cartPage,checkout:checkoutPage,'order-confirmation':orderConfirmationPage,wishlist:wishlistPage,compare:comparePage,'quick-order':quickOrderPage,'saved-lists':savedListsPage,account:accountPage,brands:brandsPage,wholesale:wholesalePage,about:()=>staticPage('about'),contact:()=>staticPage('contact'),faq:faqPage,shipping:()=>staticPage('shipping'),returns:()=>staticPage('returns'),privacy:()=>staticPage('privacy'),terms:()=>staticPage('terms'),'404':notFound,offline:()=>pageHero('OFFLINE',t('أنت غير متصل بالإنترنت','You are offline'),t('يمكنك الرجوع للصفحات التي فتحتها سابقًا، وبعض البيانات قد لا تتحدث حتى يعود الاتصال.','You can revisit cached pages; some data may not update until you are online.'))}[pg]||notFound;main.innerHTML=f()}
let installPrompt=null;let pwaSetupDone=false;function setupPWA(){if(pwaSetupDone)return;pwaSetupDone=true;if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;const b=qs('[data-install]');if(b)b.hidden=false});qs('[data-install]')?.addEventListener('click',async()=>{if(!installPrompt)return;installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;qs('[data-install]').hidden=true})}
let bindController=null;
function bind(){
 if(bindController)bindController.abort(); bindController=new AbortController(); const sig={signal:bindController.signal};
 const on=(el,ev,fn,opts={})=>el&&el.addEventListener(ev,fn,{...opts,signal:bindController.signal});
 on(qs('[data-lang]'),'click',()=>{const u=new URL(location.href);if(isAR)u.searchParams.set('lang','en');else u.searchParams.delete('lang');location.href=u.pathname.split('/').pop()+u.search});
 on(qs('[data-backdrop]'),'click',closeUI);qsa('[data-close]').forEach(b=>on(b,'click',closeUI));qsa('[data-cart-open]').forEach(b=>on(b,'click',()=>openUI(qs('[data-cart-drawer]'))));on(qs('[data-wish-open]'),'click',()=>openUI(qs('[data-wish-drawer]')));on(qs('[data-menu]'),'click',()=>openUI(qs('[data-mobile-menu]')));qsa('[data-search-open]').forEach(b=>on(b,'click',()=>{openUI(qs('[data-search-modal]'));renderSearch('');setTimeout(()=>qs('[data-search-input]')?.focus(),40)}));on(qs('[data-search-input]'),'input',e=>{renderSearch(e.target.value);const sp=qs('[data-search-page]');if(sp)sp.href=url('search.html',{q:e.target.value})});on(qs('[data-search-input]'),'keydown',e=>{if(e.key==='Enter'){e.preventDefault();saveSearch(e.target.value);location.href=url('search.html',{q:e.target.value})}});
 on(document,'click',e=>{const a=e.target.closest('[data-add]');if(a){e.preventDefault();addCart(a.dataset.add)}const w=e.target.closest('[data-wish]');if(w){e.preventDefault();toggleWish(w.dataset.wish)}const cp=e.target.closest('[data-compare]');if(cp){e.preventDefault();toggleCompare(cp.dataset.compare)}const r=e.target.closest('[data-remove]');if(r){const i=+r.closest('[data-line]').dataset.line;cart.splice(i,1);saveCart()}const inc=e.target.closest('[data-inc]'),dec=e.target.closest('[data-dec]');if(inc||dec){const i=+(inc||dec).closest('[data-line]').dataset.line;cart[i].qty=Math.max(1,cart[i].qty+(inc?1:-1));saveCart()}const pr=e.target.closest('[data-page-remove]'),pi=e.target.closest('[data-page-inc]'),pd=e.target.closest('[data-page-dec]');if(pr||pi||pd){const i=+(pr||pi||pd).closest('[data-page-line]').dataset.pageLine;if(pr)cart.splice(i,1);else cart[i].qty=Math.max(1,cart[i].qty+(pi?1:-1));set(K.cart,cart);renderAll()}const ps=e.target.closest('[data-page-save]');if(ps){if(!wish.includes(ps.dataset.pageSave))wish.unshift(ps.dataset.pageSave);set(K.wish,wish);toast(t('تم الحفظ في المفضلة','Saved to wishlist'))}const dl=e.target.closest('[data-list-delete]');if(dl){delete lists[dl.dataset.listDelete];set(K.lists,lists);renderAll()}const la=e.target.closest('[data-list-addall]');if(la){(lists[la.dataset.listAddall]||[]).forEach(id=>addCart(id));toast(t('تمت إضافة القائمة للسلة','List added to cart'))}const ld=e.target.closest('[data-list-dialog]');if(ld){if(!Object.keys(lists).length){lists[t('قائمتي الأولى','My first list')]=[];set(K.lists,lists)}addToList(ld.dataset.listDialog,Object.keys(lists)[0])}const th=e.target.closest('[data-thumb]');if(th){const img=qs('[data-gallery-main] img'),main=qs('[data-gallery-main]');if(img)img.src=th.dataset.thumb;if(main)main.dataset.zoomSrc=th.dataset.thumb;qsa('[data-thumb]').forEach(x=>x.classList.toggle('is-active',x===th))}const gm=e.target.closest('[data-gallery-main]');if(gm){const zi=qs('[data-zoom-img]');if(zi)zi.src=gm.dataset.zoomSrc;openUI(qs('[data-zoom]'))}const ns=e.target.closest('[data-next-step]');if(ns){const cur=ns.closest('[data-checkout-step]');const required=qsa('[required]',cur);if(required.some(x=>!x.reportValidity()))return;showCheckoutStep(+ns.dataset.nextStep)}const pv=e.target.closest('[data-prev-step]');if(pv)showCheckoutStep(+pv.dataset.prevStep);const ro=e.target.closest('[data-reorder]');if(ro){const o=orders.find(x=>x.id===ro.dataset.reorder);if(o){o.items.forEach(l=>addCart(l.id,l.qty,l.variantIndex));location.href=url('cart.html')}}const rc=e.target.closest('[data-restore-cart]');if(rc){cart=get('gr17_saved_cart',[]);saveCart();location.href=url('cart.html')}});
 on(qs('[data-product-add]'),'click',e=>{addCart(e.currentTarget.dataset.productAdd,+qs('[data-qty]')?.value||1,+qs('[data-variant]')?.value||0);openUI(qs('[data-cart-drawer]'))});on(qs('[data-qplus]'),'click',()=>qs('[data-qty]').value=(+qs('[data-qty]').value||1)+1);on(qs('[data-qminus]'),'click',()=>qs('[data-qty]').value=Math.max(1,(+qs('[data-qty]').value||1)-1));on(qs('[data-variant]'),'change',e=>{const p=product(params.get('id')),v=variantInfo(p,+e.target.value);qs('[data-product-price]').textContent=money(v.price)});
 on(qs('[data-filter-form]'),'submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),ex={};for(const [k,v] of fd.entries())if(v)ex[k]=v;location.href=url('collection.html',ex)});on(qs('[data-qofilter]'),'input',e=>qsa('[data-qorow]').forEach(r=>r.hidden=!r.dataset.search.includes(norm(e.target.value))));on(qs('[data-qoadd]'),'click',()=>{let n=0;qsa('[data-qoqty]').forEach(i=>{const q=+i.value||0;if(q>0){addCart(i.dataset.qoqty,q);i.value=0;n+=q}});if(!n)toast(t('حدد كمية لمنتج واحد على الأقل','Set a quantity for at least one product'))});on(qs('[data-create-list]'),'click',()=>{const i=qs('[data-new-list]'),n=i?.value.trim();if(!n)return;lists[n]=lists[n]||[];set(K.lists,lists);renderAll()});on(qs('[data-coupon-form]'),'submit',e=>{e.preventDefault();coupon=String(new FormData(e.currentTarget).get('coupon')||'').trim().toUpperCase();if(coupon&&coupon!=='WELCOME10'){toast(t('الرمز غير معروف في نسخة العرض','Code is not recognized in this preview'));coupon=''}set(K.coupon,coupon);renderAll()});on(qs('[data-save-cart]'),'click',()=>{set('gr17_saved_cart',cart);toast(t('تم حفظ السلة على هذا الجهاز','Cart saved on this device'))});on(qs('[data-checkout-form]'),'input',e=>{const fd=new FormData(e.currentTarget);set(K.draft,Object.fromEntries(fd.entries()))});on(qs('[data-checkout-form]'),'submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget),customer=Object.fromEntries(fd.entries());const id='GR-'+new Date().toISOString().slice(2,10).replaceAll('-','')+'-'+Math.random().toString(36).slice(2,6).toUpperCase();const o={id,date:new Date().toISOString(),customer,items:cart.map(x=>({...x})),subtotal:subtotal(),discount:discount(),total:total()};orders=[o,...orders].slice(0,20);set(K.orders,orders);cart=[];set(K.cart,cart);set(K.draft,{});location.href=url('order-confirmation.html',{order:id})});qsa('[data-contact-form],[data-quote-form]').forEach(f=>on(f,'submit',e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.currentTarget).entries());let leads=get('gr17_forms',[]);leads.unshift({type:e.currentTarget.hasAttribute('data-quote-form')?'quote':'contact',date:new Date().toISOString(),...fd});set('gr17_forms',leads.slice(0,20));e.currentTarget.reset();toast(t('تم حفظ النموذج على هذا الجهاز','Form saved on this device'))}));on(document,'keydown',e=>{if(e.key==='Escape')closeUI()});
 // Swipe gallery on touch/pointer devices.
 const gallery=qs('[data-gallery-main]');let sx=null;if(gallery){on(gallery,'pointerdown',e=>{sx=e.clientX});on(gallery,'pointerup',e=>{if(sx===null)return;const dx=e.clientX-sx;sx=null;if(Math.abs(dx)<45)return;const thumbs=qsa('[data-thumb]');if(thumbs.length<2)return;let i=Math.max(0,thumbs.findIndex(x=>x.classList.contains('is-active')));i=(i+(dx<0?1:-1)+thumbs.length)%thumbs.length;thumbs[i].click()})}
 setupPWA();
}
function showCheckoutStep(n){qsa('[data-checkout-step]').forEach(x=>x.hidden=+x.dataset.checkoutStep!==n);qsa('[data-step-dot]').forEach(x=>x.classList.toggle('is-active',+x.dataset.stepDot<=n));scrollTo({top:0,behavior:'smooth'})}
